mapper.select:
SELECT tenant_id,user_id,id AS session_id FROM ai_operation_conversation
WHERE id=#{session} AND CAST(tenant_id AS BINARY)=#{tenant}
  AND CAST(user_id AS BINARY)=#{user} AND CAST(id AS BINARY)=#{session} AND status IN ('ACTIVE','ARCHIVED')

SELECT tenant_id,user_id,id AS session_id FROM ai_customer_service_conversation
WHERE id=#{session} AND CAST(tenant_id AS BINARY)=#{tenant}
  AND CAST(user_id AS BINARY)=#{user} AND CAST(id AS BINARY)=#{session} AND status IN ('ACTIVE','ARCHIVED')

SELECT  FROM ai_memory_version v JOIN ai_memory_decision d ON d.tenant_id=v.tenant_id AND d.id=v.decision_id
  JOIN ai_memory_item i ON i.tenant_id=v.tenant_id AND i.id=v.item_id
WHERE v.tenant_id=#{tenant} AND v.item_id=#{item} AND v.id=#{version}
